CustomField.formula:
IF(ISNULL(Scheduled_Service_Date__c), "",(
LPAD(TEXT(Day(DateValue(Scheduled_Service_Date__c ))) ,2, '0' ) +'/'+ LPAD ( TEXT( MONTH( DateValue(Scheduled_Service_Date__c) ) ) ,2, '0' ) +'/'+ TEXT( YEAR( DateValue(Scheduled_Service_Date__c ) ) ) + ' - ' + LEFT(TEXT(TIMEVALUE(Scheduled_Service_Date__c + (0/24))), 5)
)
)
